INSERT OR IGNORE INTO schedules (id,payload,updated_at) VALUES (1,'{"names":["뉴키","시오","단우","이코","야키","후니","현이"],"courts":5,"rounds":4,"schedule":[{"round":1,"g":[["단우","시오","후니","뉴키"]],"rest":["야키","현이","이코"]},{"round":2,"g":[["이코","야키","현이","시오"]],"rest":["단우","뉴키","후니"]},{"round":3,"g":[["뉴키","야키","이코","후니"]],"rest":["단우","현이","시오"]},{"round":4,"g":[["단우","현이","시오","뉴키"]],"rest":["야키","후니","이코"]}]}','2026-09-11T05:44:12.372Z');
INSERT OR IGNORE INTO board_posts (id,kind,payload,version,last_operation,created_at,updated_at) VALUES ('c887f83f-f42a-4f86-8447-3d65873a3958','notice','{"title":"🎁 운영진 이벤트 🎁","body":"[콕 지원 쿠폰]\n셔틀콕 1개 교환 쿠폰입니다.\n\n- 당일 사용 불가\n- 회원만 사용 가능\n- 쿠폰을 여러 장 모아서 사용 가능\n\n[쿠폰 지급 기준]\n\n1. 게스트 초대 감사 쿠폰\n\n새로운 게스트를 초대하거나 모임 방문에 기여한 회원에게 내부 기준에 따라 지급합니다.\n\n2. 신규회원 가입 쿠폰\n\n게스트가 회원으로 가입한 뒤 다음 모임에 1회 참석하면 지급합니다.\n\n3. MVP 쿠폰\n\n대진이 진행된 모임에서 승수가 가장 많은 회원에게 지급합니다.\n\n- 월 최대 2장 지급\n- 게스트, 늦참, 늦댓글로 경기 일부를 빠진 경우 MVP 선정에서 제외됩니다.\n\n[월별 MVP 쿠폰 지급 내역]\n\n6월\n- 4주차: 슝슝, 후니, 우하, 뚜기\n\n7월\n- 2주차: 단우, 후니, 두진, 우하\n- 3주차: 아몬드, 아만\n- 4주차: 로토\n\n8월\n- 1주차: 머우\n- 2주차: 후니\n- 3주차: 구름, 쿠쿠\n- 4주차: 새로, 주밤, 머우\n\n9월\n- 1주차: 동\n\n[감사 및 신규 가입 쿠폰]\n\n7월\n두진, 소고기, 쿠쿠, 쵸이, 제리, 뚜기, 시오\n\n8월\n바유, 민석, 쿠쿠, 피글렛\n\n9월\n주밤\n\n[상품권 이벤트]\n\n1만 원 상품권\n\n- 6월 1차 당첨자: 두진, 리버\n- 9월 2차 당첨자: 추후 안내\n\n많은 참여와 새로운 회원 초대를 부탁드립니다.\n\n\n쿠폰 누락자 및 미지급자\n- 구름 1\n- 새로 1"}',2,'import-codex-site','2026-09-11T07:34:12.784Z','2026-09-11T07:36:52.456Z');
INSERT OR IGNORE INTO board_posts (id,kind,payload,version,last_operation,created_at,updated_at) VALUES ('a21bea76-5512-4589-9a09-d41ab01a5ba3','notice','{"title":"🐘 콕끼리 공지사항🐘","body":"1. 정모 관련(소정모는 매주 수요일 19시)\n ▶ 매주 토요일 1시 전,후(3h)\n ▶ 대진 5게임(랜덤 동일2 인접2)\n ▶ 출석1점 승패 1점 랜덤합산 X \n ▶ 시드 투명성 공개 주 1회 진행\n ▶ 게임수 보장 순위 \n      회원>운영진>늦참자>게스트\n ▶운영진 주최 \"벙개\" 16인이상시\n     대진으로 진행 후 시드 반영\n    \n2. 지정콕 사용 26,000원이상\n▶KBB79 / 26,000원에 준하는 셔틀콕 제출 부탁드립니다.\n제출 가능 : 더블랙, 4000, 79 네오 등\n▶콕 없을시 2,500원 운영진에게 구매\n🔵10/1일자 기준 모두kbb79 통일 예정\n\n3. 게스트관련\n ▶정모(토) 화요일 0시부터 투표가능\n ▶게스트 정산은 초대자가 합산정산\n ▶게스트는 참여횟수무관 필수 소개\n ▶운영진 사전 연락시 선댓글 가능\n ▶게스트양식 닉넴✔️년생✔️급수\n\n4. 투표 및 대관 방식\n ▶ 매주 카톡에 게시 예정\n ▶ 입금 계좌 1/N 대관자\n ▶ 마감 및 정산 시간- 일정 2일전\n\n5. 도움되는 영상🏸\n ▶ 유튜브 \"인호코치\"\n ▶ 유튜브  \"윤2콕\"\n ▶ 유튜브  \"민턴독학 아나조\"\n\n6. 가입 관련 및 회원관리\n ▶누구나 승인방 링크 공유가능\n ▶게스트 1회 참여시 가입가능\n ▶유령회원은 개별 안내 및 소명 요청"}',4,'import-codex-site','2026-09-11T07:19:33.151Z','2026-09-11T07:35:48.903Z');
INSERT OR IGNORE INTO board_posts (id,kind,payload,version,last_operation,created_at,updated_at) VALUES ('legacy-schedule','schedule','{"title":"테스트용 대진","names":["로토","이코","뉴키","단우","구구","백구"],"participantIds":["member-7","member-11","member-12","member-14","member-17","member-18"],"courts":5,"rounds":4,"schedule":[{"round":1,"g":[["백구","로토","뉴키","구구"]],"rest":["이코","단우"]},{"round":2,"g":[["구구","로토","백구","이코"]],"rest":["뉴키","단우"]},{"round":3,"g":[["백구","구구","단우","로토"]],"rest":["이코","뉴키"]},{"round":4,"g":[["뉴키","로토","백구","이코"]],"rest":["단우","구구"]}]}',3,'import-codex-site','2026-09-11T05:44:12.372Z','2026-09-11T07:21:04.098Z');
